class ErroValidacao extends Error {
  constructor(mensagem, campo) {
    super(mensagem);
    this.name = "ErroValidacao";
    this.campo = campo;
  }
}

function validarIdade(idade) {
  if (typeof idade !== "number" || idade < 0) {
    throw new ErroValidacao("A idade tem de ser um número positivo", "idade");
  }
  return idade;
}

try {
  validarIdade(-5);
} catch (erro) {
  if (erro instanceof ErroValidacao) {
    console.log(`Campo inválido: ${erro.campo} - ${erro.message}`);
  }
}

class AppError extends Error {
  constructor(mensagem, codigoHttp = 500) {
    super(mensagem);
    this.name = this.constructor.name;
    this.codigoHttp = codigoHttp;
  }
}

class ErroNaoEncontrado extends AppError {
  constructor(recurso) {
    super(`${recurso} não encontrado`, 404);
  }
}

class ErroNaoAutorizado extends AppError {
  constructor(mensagem = "Acesso não autorizado") {
    super(mensagem, 401);
  }
}

function tratarErro(erro) {
  if (erro instanceof AppError) {
    console.log(`[${erro.codigoHttp}] ${erro.name}: ${erro.message}`);
  } else {
    console.log("Erro inesperado:", erro);
  }
}

tratarErro(new ErroNaoEncontrado("Utilizador"));
tratarErro(new ErroNaoAutorizado());

async function carregarPerfil(id) {
  try {
    const resposta = await fetch(`/api/utilizadores/${id}`);
    if (!resposta.ok) {
      throw new Error(`Pedido falhou com estado ${resposta.status}`);
    }
    return await resposta.json();
  } catch (erroOriginal) {
    throw new Error("Não foi possível carregar o perfil", { cause: erroOriginal });
  }
}

(async () => {
  try {
    await carregarPerfil(42);
  } catch (erro) {
    console.log(erro.message);        // "Não foi possível carregar o perfil"
    console.log(erro.cause?.message); // mensagem do erro original
  }
})();

