class ErroSerializavel extends Error {
  constructor(mensagem, detalhes) {
    super(mensagem);
    this.name = "ErroSerializavel";
    this.detalhes = detalhes;
  }

  toJSON() {
    return {
      nome: this.name,
      mensagem: this.message,
      detalhes: this.detalhes,
    };
  }
}

const erroPersonalizado = new ErroSerializavel("Pagamento recusado", { codigo: "CARTAO_INVALIDO" });
console.log(JSON.stringify(erroPersonalizado));
