function converterParaMaiusculas(valor) {
  if (typeof valor !== "string") {
    throw new TypeError("Esperava uma string");
  }
  return valor.toUpperCase();
}

try {
  console.log(converterParaMaiusculas("ola"));
  console.log(converterParaMaiusculas(123));
} catch (erro) {
  console.log(erro.name, "-", erro.message);
}

class ErroSaldoInsuficiente extends Error {
  constructor(saldoAtual, valorPedido) {
    super(`Saldo insuficiente: disponível ${saldoAtual}, pedido ${valorPedido}`);
    this.name = "ErroSaldoInsuficiente";
    this.saldoAtual = saldoAtual;
    this.valorPedido = valorPedido;
  }
}

function levantar(saldo, valor) {
  if (valor > saldo) {
    throw new ErroSaldoInsuficiente(saldo, valor);
  }
  return saldo - valor;
}

try {
  console.log(levantar(100, 250));
} catch (erro) {
  if (erro instanceof ErroSaldoInsuficiente) {
    console.log(
      `Não é possível levantar ${erro.valorPedido}: só há ${erro.saldoAtual} disponível`
    );
  } else {
    throw erro;
  }
}

function lerConfiguracao(json) {
  try {
    return JSON.parse(json);
  } catch (erroOriginal) {
    throw new Error("Configuração inválida", { cause: erroOriginal });
  }
}

try {
  lerConfiguracao("{ chave: sem aspas }");
} catch (erro) {
  console.log(erro.message);
  console.log(erro.cause instanceof SyntaxError);
  console.log(erro.cause.message);
}

class ErroApp extends Error {
  constructor(mensagem, codigoHttp) {
    super(mensagem);
    this.name = this.constructor.name;
    this.codigoHttp = codigoHttp;
  }
}

class ErroValidacao extends ErroApp {
  constructor(mensagem) {
    super(mensagem, 400);
  }
}

class ErroNaoEncontrado extends ErroApp {
  constructor(mensagem) {
    super(mensagem, 404);
  }
}

class ErroConflito extends ErroApp {
  constructor(mensagem) {
    super(mensagem, 409);
  }
}

const utilizadoresValidos = new Set([1, 2, 3]);
const utilizadoresComPedido = new Set();

function processarPedido({ utilizadorId, itens }) {
  if (!utilizadoresValidos.has(utilizadorId)) {
    throw new ErroNaoEncontrado(`Utilizador ${utilizadorId} não encontrado`);
  }
  if (!Array.isArray(itens) || itens.length === 0) {
    throw new ErroValidacao("O pedido tem de conter pelo menos um item");
  }
  if (utilizadoresComPedido.has(utilizadorId)) {
    throw new ErroConflito(`Utilizador ${utilizadorId} já tem um pedido em curso`);
  }
  utilizadoresComPedido.add(utilizadorId);
  return { estado: "aceite", utilizadorId, totalItens: itens.length };
}

function tratarPedido(pedido) {
  try {
    const resultado = processarPedido(pedido);
    console.log("Sucesso:", resultado);
  } catch (erro) {
    if (erro instanceof ErroApp) {
      console.log(`[${erro.codigoHttp}] ${erro.name}: ${erro.message}`);
    } else {
      console.log("Erro interno inesperado:", erro.message);
      throw erro;
    }
  }
}

tratarPedido({ utilizadorId: 1, itens: ["livro"] });
tratarPedido({ utilizadorId: 1, itens: ["caneta"] });
tratarPedido({ utilizadorId: 9, itens: ["livro"] });
tratarPedido({ utilizadorId: 2, itens: [] });
